import { readFileSync } from "node:fs";

// This artifact is generated by LLO's schema-bridge from execution/v1. The
// Node client derives operation identity from it instead of maintaining a
// second list of names/descriptions in Cloister.
const GENERATED_TOOLS = JSON.parse(readFileSync(
  new URL("../../../src/generated/llo-execution-tools.json", import.meta.url),
  "utf8",
));

if (!Array.isArray(GENERATED_TOOLS) || GENERATED_TOOLS.length === 0) {
  throw new Error("LLO execution tool artifact must be a non-empty array");
}

const TOOL_BY_NAME = new Map();
for (const tool of GENERATED_TOOLS) {
  if (!tool || typeof tool.name !== "string" || !tool.name.startsWith("llo_execution_")) {
    throw new Error("LLO execution tool artifact contains an invalid operation");
  }
  if (TOOL_BY_NAME.has(tool.name)) {
    throw new Error(`LLO execution tool artifact repeats ${tool.name}`);
  }
  TOOL_BY_NAME.set(tool.name, tool);
}

export const LLO_EXECUTION_OPERATIONS = Object.freeze(
  GENERATED_TOOLS.map((tool) => tool.name),
);

const OPERATION_BY_SUFFIX = new Map(
  LLO_EXECUTION_OPERATIONS.map((name) => [name.slice("llo_execution_".length), name]),
);

function operation(suffix) {
  const name = OPERATION_BY_SUFFIX.get(suffix);
  if (!name) throw new Error(`generated LLO execution operation is missing: ${suffix}`);
  return name;
}

export function lloExecutionTools() {
  return GENERATED_TOOLS.map((tool) => structuredClone(tool));
}

function request(name, fields = {}) {
  if (!TOOL_BY_NAME.has(name)) {
    throw new Error(`unsupported generated LLO execution operation: ${name}`);
  }
  const value = { op: name, ...fields };
  validateLloExecutionRequest(value);
  return value;
}

function requireObject(value, label) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${label} must be an object`);
  }
  return value;
}

function resolveRef(schema, root) {
  if (typeof schema?.$ref !== "string") return schema;
  const prefix = "#/$defs/";
  if (!schema.$ref.startsWith(prefix)) {
    throw new Error(`unsupported generated LLO schema reference ${schema.$ref}`);
  }
  const resolved = root.$defs?.[schema.$ref.slice(prefix.length)];
  if (!resolved) throw new Error(`unresolved generated LLO schema reference ${schema.$ref}`);
  return resolved;
}

function validateValue(value, schema, root, path) {
  const resolved = resolveRef(schema, root);
  if (resolved.const !== undefined && value !== resolved.const) {
    throw new TypeError(`${path} must equal ${JSON.stringify(resolved.const)}`);
  }
  if (Array.isArray(resolved.enum) && !resolved.enum.includes(value)) {
    throw new TypeError(`${path} has an invalid enum value`);
  }
  if (typeof resolved.minimum === "number" && typeof value === "number" && value < resolved.minimum) {
    throw new TypeError(`${path} must be >= ${resolved.minimum}`);
  }
  switch (resolved.type) {
    case "object": {
      if (!value || typeof value !== "object" || Array.isArray(value)) {
        throw new TypeError(`${path} must be an object`);
      }
      for (const required of resolved.required ?? []) {
        if (!Object.hasOwn(value, required)) {
          throw new TypeError(`${path}.${required} is required by the generated schema`);
        }
      }
      for (const [name, child] of Object.entries(value)) {
        const childSchema = resolved.properties?.[name];
        if (!childSchema) {
          if (resolved.additionalProperties === false) {
            throw new TypeError(`${path}.${name} is not declared by the generated schema`);
          }
          continue;
        }
        validateValue(child, childSchema, root, `${path}.${name}`);
      }
      return;
    }
    case "array":
      if (!Array.isArray(value)) throw new TypeError(`${path} must be an array`);
      for (const [index, child] of value.entries()) {
        validateValue(child, resolved.items, root, `${path}[${index}]`);
      }
      return;
    case "string":
      if (typeof value !== "string") throw new TypeError(`${path} must be a string`);
      return;
    case "integer":
      if (!Number.isInteger(value)) throw new TypeError(`${path} must be an integer`);
      return;
    case "number":
      if (typeof value !== "number" || !Number.isFinite(value)) {
        throw new TypeError(`${path} must be a number`);
      }
      return;
    case "boolean":
      if (typeof value !== "boolean") throw new TypeError(`${path} must be a boolean`);
      return;
    case "null":
      if (value !== null) throw new TypeError(`${path} must be null`);
      return;
    default:
      throw new Error(`unsupported generated LLO schema type at ${path}`);
  }
}

/** Validate one complete UDS request against the pinned generated artifact. */
export function validateLloExecutionRequest(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError("LLO execution request must be an object");
  }
  const tool = TOOL_BY_NAME.get(value.op);
  if (!tool) throw new TypeError(`unknown generated LLO execution operation: ${value.op}`);
  const input = { ...value };
  delete input.op;
  validateValue(input, tool.inputSchema, tool.inputSchema, "request");
  return value;
}

export const lloExecutionRequest = Object.freeze({
  capabilities: () => request(operation("capabilities")),
  status: (runId = "") => request(operation("status"), { runId }),
  provision: (backendClass, idempotencyKey) => request(
    operation("provision"),
    { backendClass, idempotencyKey },
  ),
  start: (spec, grant) => request(
    operation("start"),
    {
      spec: requireObject(spec, "LLO execution spec"),
      grant: requireObject(grant, "LLO execution grant"),
    },
  ),
  inspect: (runId, afterSequence = 0) => request(
    operation("inspect"),
    { runId, afterSequence },
  ),
  cancel: (runId, idempotencyKey = "") => request(
    operation("cancel"),
    { runId, idempotencyKey },
  ),
  collect: (runId) => request(operation("collect"), { runId }),
  cleanup: (runId, idempotencyKey = "") => request(
    operation("cleanup"),
    { runId, idempotencyKey },
  ),
});
